typedef enum {
    SHIFT_IDLE,
    SHIFT_ACTIVE
} ShiftState;

static ShiftState g_shift_state;
static uint8_t g_requested_gear;
static uint16_t g_pressure_command;

void HandleShiftRequest(uint8_t target) {
    g_shift_state = SHIFT_ACTIVE;
    g_requested_gear = target;
    if (!IsGearSupported(target)) {
        return;
    }
    g_pressure_command = PressureForGear(target);
}

typedef struct {
    uint16_t turbine_rpm;
    int8_t selected_gear;
    uint32_t sample_tick;
} SensorSnapshot;

static SensorSnapshot g_snapshot;

void PeriodicSampleTask(void) {
    g_snapshot.turbine_rpm = ReadTurbineRpm();
    g_snapshot.selected_gear = ReadSelectedGear();
    g_snapshot.sample_tick = ReadSystemTick();
}

void DiagnosticEvent(void) {
    SensorSnapshot local;
    local.turbine_rpm = g_snapshot.turbine_rpm;
    local.selected_gear = g_snapshot.selected_gear;
    local.sample_tick = g_snapshot.sample_tick;
    PublishSnapshot(local);
}

typedef struct {
    uint8_t requested_gear;
    uint16_t pressure_command;
    uint32_t update_tick;
} ShiftSnapshot;

static ShiftSnapshot g_shift_snapshot;
static StateLock g_state_lock;

void PeriodicShiftTask(void) {
    uint8_t gear = ReadValidatedRequestedGear();
    uint16_t pressure = PressureForGear(gear);
    uint32_t tick = ReadSystemTick();

    LockState(&g_state_lock);
    g_shift_snapshot.requested_gear = gear;
    g_shift_snapshot.pressure_command = pressure;
    g_shift_snapshot.update_tick = tick;
    UnlockState(&g_state_lock);
}

void ShiftStatusEvent(void) {
    ShiftSnapshot local;

    LockState(&g_state_lock);
    local = g_shift_snapshot;
    UnlockState(&g_state_lock);

    PublishShiftStatus(local);
}
